public synchronized void acquire() throws InterruptedException {
        prepareAcquire();

        boolean canPass;
        do {
            canPass = acquirePermit();
            if (!canPass) {
                wait();
            }
        } while (!canPass);
    }

public synchronized boolean tryAcquire() {
        prepareAcquire();
        return acquirePermit();
    }

