public static double min(final double... array) {
        Validate.notNull(array, "array");
        Validate.isTrue(array.length != 0, "Array cannot be empty.");

        // Finds and returns min
        double min = array[0];
        for (int i = 1; i < array.length; i++) {
            min = min(array[i], min);
        }

        return min;
    }

public static float min(final float... array) {
        Validate.notNull(array, "array");
        Validate.isTrue(array.length != 0, "Array cannot be empty.");

        // Finds and returns min
        float min = array[0];
        for (int i = 1; i < array.length; i++) {
            min = min(array[i], min);
        }

        return min;
    }

public static double min(final double a, final double b, final double c) {
        return min(min(a, b), c);
    }

public static double min(final double a, final double b) {
        if (Double.isNaN(a)) {
            return b;
        } else
        if (Double.isNaN(b)) {
            return a;
        } else {
            return Math.min(a, b);
        }
    }

public static float min(final float a, final float b, final float c) {
        return min(min(a, b), c);
    }

public static float min(final float a, final float b) {
        if (Float.isNaN(a)) {
            return b;
        } else
        if (Float.isNaN(b)) {
            return a;
        } else {
            return Math.min(a, b);
        }
    }

public static double max(final double... array) {
        Validate.notNull(array, "array");
        Validate.isTrue(array.length != 0, "Array cannot be empty.");

        // Finds and returns max
        double max = array[0];
        for (int j = 1; j < array.length; j++) {
            max = max(array[j], max);
        }

        return max;
    }

public static float max(final float... array) {
        Validate.notNull(array, "array");
        Validate.isTrue(array.length != 0, "Array cannot be empty.");

        // Finds and returns max
        float max = array[0];
        for (int j = 1; j < array.length; j++) {
            max = max(array[j], max);
        }

        return max;
    }

public static double max(final double a, final double b, final double c) {
        return max(max(a, b), c);
    }

public static double max(final double a, final double b) {
        if (Double.isNaN(a)) {
            return b;
        } else
        if (Double.isNaN(b)) {
            return a;
        } else {
            return Math.max(a, b);
        }
    }

public static float max(final float a, final float b, final float c) {
        return max(max(a, b), c);
    }

public static float max(final float a, final float b) {
        if (Float.isNaN(a)) {
            return b;
        } else
        if (Float.isNaN(b)) {
            return a;
        } else {
            return Math.max(a, b);
        }
    }

@Override
    public int compare(final Object o1, final Object o2) {
        if (o1 == null && o2 == null) {
            return 0;
        }
        if (o1 == null) {
            return 1;
        }
        if (o2 == null) {
            return -1;
        }
        final String string1 = o1.toString();
        final String string2 = o2.toString();
        // No guarantee that toString() returns a non-null value, despite what Spotbugs thinks.
        if (string1 == null && string2 == null) {
            return 0;
        }
        if (string1 == null) {
            return 1;
        }
        if (string2 == null) {
            return -1;
        }
        return string1.compareTo(string2);
    }

public boolean between(final A b, final A c) {
            return betweenOrdered(b, c) || betweenOrdered(c, b);
        }

public boolean betweenExclusive(final A b, final A c) {
            return betweenOrderedExclusive(b, c) || betweenOrderedExclusive(c, b);
        }

private boolean betweenOrdered(final A b, final A c) {
            return greaterThanOrEqualTo(b) && lessThanOrEqualTo(c);
        }

private boolean betweenOrderedExclusive(final A b, final A c) {
            return greaterThan(b) && lessThan(c);
        }

